// 与上次运行对比，找出阶段发生跨越的城市
const cities = $input.first().json.cities || [];
const staticData = $getWorkflowStaticData('global');
const last = staticData.phases || {};
const changes = [];
for (const c of cities) {
  if (last[c.cityCode] && last[c.cityCode] !== c.phase) {
    changes.push(`⚡ ${c.city}: ${last[c.cityCode]} → ${c.phase}（二手去化周期 ${c.secondHand.inventoryCycle ?? '—'} 月，数据日期 ${c.dataDate}）`);
  }
  last[c.cityCode] = c.phase;
}
staticData.phases = last;
return changes.length ? [{ json: { message: changes.join('\n') } }] : [];
